import { CiPlay1 } from "react-icons/ci";
import { LuSquareLibrary } from "react-icons/lu";

import type { Manga } from "@/lib/catalog";
import { legacyMangaCover } from "@/lib/catalog";
import { MediaImage } from "@/components/MediaImage/page";
import styles from "./mangainfo.module.css";

function MangaInfo({ manga, firstChapterId }: { manga: Manga; firstChapterId?: string }) {
  const trackers = Object.entries(manga.trackers ?? {}).filter(([, url]) => url);

  return (
    <section className={styles.mangaInfoContainer}>
      <div>
        <div className={styles.mangaWrapper}>
          <MediaImage className={styles.mangaCover} source={manga.mangaCover || legacyMangaCover(manga.title) || manga.previewImage} alt={`Capa de ${manga.title}`} />
        </div>
        <div className={styles.btnWrapper}>
          <button className={styles.btnAdd} disabled><LuSquareLibrary size={20} /><span>Adicionar à Biblioteca</span></button>
          {firstChapterId && <a className={styles.btnRead} href={`/title/${manga.id}/${firstChapterId}`}><CiPlay1 size={20} /><span>Iniciar leitura</span></a>}
        </div>
      </div>
      <div className={styles.mangaInfo}>
        <h1 className={styles.mangaTitle}>{manga.title}</h1>
        <p className={styles.sinopse}>{manga.description}</p>
        <div className={styles.genderDemographicContainer}>
          <div className={styles.genderContainer}>
            <h3 className={styles.genderTitle}>Gêneros</h3>
            <div className={styles.genders}>{manga.genders.map((gender) => <span className={styles.gender} key={gender}>{gender}</span>)}</div>
          </div>
        </div>
        <div className={styles.mangakaContainer}>
          <h3 className={styles.mangakaTitle}>Mangaka</h3>
          <div className={styles.mangakas}><span className={styles.mangaka}>{manga.mangaka}</span></div>
        </div>
        {trackers.length > 0 && (
          <div className={styles.trackersContainer}>
            <h3 className={styles.trackersTitle}>Trackers</h3>
            <div className={styles.trackers}>{trackers.map(([name, url]) => <a href={String(url)} key={name} target="_blank" rel="noreferrer">{name}</a>)}</div>
          </div>
        )}
      </div>
    </section>
  );
}

export { MangaInfo };
