import { graphqlRequest } from "./graphql";

export interface GroupStats {
  followers: number;
  mangas: number;
  chapters: number;
  views: number;
  likes: number;
}

export interface SocialMedias {
  site?: string | null;
  discord?: string | null;
  telegram?: string | null;
  x?: string | null;
  instagram?: string | null;
  facebook?: string | null;
  bluesky?: string | null;
  orkut?: string | null;
  email?: string | null;
}

export interface Group {
  id: string;
  groupImage?: string | null;
  previewImage?: string | null;
  name: string;
  description: string;
  country: string;
  stats: GroupStats;
  socialMedias?: SocialMedias | null;
  mangas?: Manga[];
}

export interface Trackers {
  myanimelist?: string | null;
  anilist?: string | null;
  animeplanet?: string | null;
}

export interface Manga {
  id: string;
  mangaCover?: string | null;
  previewImage?: string | null;
  title: string;
  description: string;
  mangaka: string;
  genders: string[];
  trackers?: Trackers | null;
}

export interface Chapter {
  id: string;
  manga: string;
  group: string;
  chapterTitle?: string | null;
  chapterNumber: number;
  pages: string[];
  createdAt: string;
  mangaInfo: Manga;
  groupInfo: Group;
}

const GROUP_FIELDS = `
  id groupImage previewImage name description country
  stats { followers mangas chapters views likes }
  socialMedias { site discord telegram x instagram facebook bluesky orkut email }
`;

const MANGA_FIELDS = `
  id mangaCover previewImage title description mangaka genders
  trackers { myanimelist anilist animeplanet }
`;

export async function getGroups() {
  const data = await graphqlRequest<{ groups: Group[] }>(`query Groups {
    groups { ${GROUP_FIELDS} }
  }`);
  return data.groups;
}

export async function getGroup(id: string) {
  const data = await graphqlRequest<{ group: Group | null }>(`query Group($id: ID!) {
    group(id: $id) { ${GROUP_FIELDS} mangas { ${MANGA_FIELDS} } }
  }`, { id });
  return data.group;
}

export async function getMangas() {
  const data = await graphqlRequest<{ mangas: Manga[] }>(`query Mangas {
    mangas { ${MANGA_FIELDS} }
  }`);
  return data.mangas;
}

export async function getManga(id: string) {
  const data = await graphqlRequest<{ manga: Manga | null }>(`query Manga($id: ID!) {
    manga(id: $id) { ${MANGA_FIELDS} }
  }`, { id });
  return data.manga;
}

export async function getChaptersByManga(mangaId: string) {
  const data = await graphqlRequest<{ chaptersByManga: Chapter[] }>(`query Chapters($mangaId: ID!) {
    chaptersByManga(mangaId: $mangaId) {
      id manga group chapterTitle chapterNumber pages createdAt
      groupInfo { ${GROUP_FIELDS} }
      mangaInfo { ${MANGA_FIELDS} }
    }
  }`, { mangaId });
  return data.chaptersByManga;
}

export async function getChapter(id: string) {
  const data = await graphqlRequest<{ chapter: Chapter | null }>(`query Chapter($id: ID!) {
    chapter(id: $id) {
      id manga group chapterTitle chapterNumber pages createdAt
      groupInfo { ${GROUP_FIELDS} }
      mangaInfo { ${MANGA_FIELDS} }
    }
  }`, { id });
  return data.chapter;
}

export async function getLatestChapters(limit = 40) {
  const data = await graphqlRequest<{ latestChapters: Chapter[] }>(`query LatestChapters($limit: Int!) {
    latestChapters(limit: $limit) {
      id manga group chapterTitle chapterNumber pages createdAt
      groupInfo { ${GROUP_FIELDS} }
      mangaInfo { ${MANGA_FIELDS} }
    }
  }`, { limit });
  return data.latestChapters;
}

export function mediaUrl(value?: string | null) {
  if (!value) return null;
  if (/^(https?:|data:|blob:|\/)/i.test(value)) return value;
  const cid = value.replace(/^ipfs:\/\//i, "").replace(/^ipfs\//i, "");
  const gateway = (process.env.NEXT_PUBLIC_IPFS_GATEWAY ?? "https://dweb.link/ipfs/")
    .replace(/\/?$/, "/");
  return `${gateway}${cid}`;
}

const LEGACY_GROUP_IMAGES: Record<string, string> = {
  "anima regia": "/scans/anima-regia.jpg",
};

const LEGACY_MANGA_COVERS: Record<string, string> = {
  "one piece": "/one-piece.jpg",
  "ruri dragon": "/ruri-dragon.jpg",
};

export function legacyGroupImage(name: string) {
  return LEGACY_GROUP_IMAGES[name.trim().toLowerCase()] ?? null;
}

export function legacyMangaCover(title: string) {
  return LEGACY_MANGA_COVERS[title.trim().toLowerCase()] ?? null;
}
